function enableStopReorder(row){let timer=null,dragging=false,startY=0,pointerId=null;const wrap=$('#tripDestinationStops');const clear=()=>{clearTimeout(timer);timer=null};row.addEventListener('pointerdown',e=>{if(e.target.closest('button,input,select,textarea,.destination-suggestions'))return;if(e.button!==undefined&&e.button!==0)return;pointerId=e.pointerId;startY=e.clientY;clear();timer=setTimeout(()=>{dragging=true;row.classList.add('is-dragging');row.setPointerCapture?.(pointerId);if(navigator.vibrate)navigator.vibrate(20)},420)});row.addEventListener('pointermove',e=>{if(!dragging){if(Math.abs(e.clientY-startY)>10)clear();return}e.preventDefault();const siblings=[...wrap.querySelectorAll('.trip-destination-stop:not(.is-dragging)')],target=siblings.find(el=>e.clientY<el.getBoundingClientRect().top+el.offsetHeight/2);if(target)wrap.insertBefore(row,target);else wrap.appendChild(row);updateStopLabels()});const finish=()=>{clear();if(dragging){dragging=false;row.classList.remove('is-dragging');updateStopLabels()}pointerId=null};row.addEventListener('pointerup',finish);row.addEventListener('pointercancel',finish);row.addEventListener('lostpointercapture',finish)}
