function populateTripCompanions(selected=[]){const wanted=new Set(selected.map(x=>String(x).toLowerCase()));const tb=$('#tripCompanionBank');if(!tb)return;tb.innerHTML=state.companionBank.map(n=>`<button type="button" class="companion-tag ${wanted.has(n.toLowerCase())?'selected':''}" data-companion="${esc(n)}">${esc(n)}</button>`).join('');$$('#tripCompanionBank .companion-tag').forEach(b=>{let hold=null,longPressed=false,sx=0,sy=0;const cancelHold=()=>{clearTimeout(hold);hold=null};b.onclick=e=>{if(longPressed){e.preventDefault();e.stopPropagation();longPressed=false;return}b.classList.toggle('selected')};b.addEventListener('contextmenu',e=>e.preventDefault());b.addEventListener('pointerdown',e=>{if(e.button!=null&&e.button!==0)return;sx=e.clientX;sy=e.clientY;longPressed=false;cancelHold();try{b.setPointerCapture?.(e.pointerId)}catch{}hold=setTimeout(()=>{longPressed=true;const name=b.dataset.companion;showWozzaConfirm('Remove companion?',`Send “${name}” to the recycle bin?`,()=>{const selectedNow=$$('#tripCompanionBank .companion-tag.selected').map(x=>x.dataset.companion).filter(x=>x.toLowerCase()!==name.toLowerCase());state.companionRecycleBin=state.companionRecycleBin.filter(x=>String(x.name).toLowerCase()!==name.toLowerCase());state.companionRecycleBin.unshift({name,removedAt:Date.now()});state.companionBank=state.companionBank.filter(x=>x.toLowerCase()!==name.toLowerCase());populateTripCompanions(selectedNow);localStorage.setItem('wozzaworld-state',JSON.stringify(state));toast(`${name} moved to recycle bin`)},'Move to recycle bin');navigator.vibrate?.(20)},520)});b.addEventListener('pointermove',e=>{if(Math.hypot(e.clientX-sx,e.clientY-sy)>14)cancelHold()});b.addEventListener('pointerup',cancelHold);b.addEventListener('pointercancel',cancelHold)})}
